def cite(refs):
    return CITES.get(refs[0]) if refs else None


def row(disease, cid, line_stage, ttype, name, drugs, refs, uur, udd, section, stage=None,
        special="", maint=None):
    if not stage:
        stage = "Стадирование TNM не применимо; стратификация по прогностическим системам нозологии (Mayo/ISS и др.)"
    return {
        "cohort_id": cid, "disease": disease,
        "treatment": {"line_stage": line_stage, "therapy_type": ttype, "regimen_name": name},
        "drugs": drugs,
        "indications": {"stage": stage, "ecog": None, "biomarkers": []},
        "evidence": {"uur": uur, "udd": udd},
        "source": {"page": None, "section": section, "table": None, "references": refs, "citation": cite(refs)},
        "special_conditions": special, "maintenance_therapy": maint,
    }


